-- READ ONLY: inspect existing Work Permit columns, foreign keys, and triggers.
select table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name in ('work_permits','work_permit_workers','work_permit_approvals','work_permit_checklists','work_permit_security_links') order by table_name,ordinal_position;
select tc.table_name,kcu.column_name,ccu.table_name as foreign_table_name,ccu.column_name as foreign_column_name,tc.constraint_name from information_schema.table_constraints tc join information_schema.key_column_usage kcu on tc.constraint_name=kcu.constraint_name and tc.constraint_schema=kcu.constraint_schema join information_schema.constraint_column_usage ccu on ccu.constraint_name=tc.constraint_name and ccu.constraint_schema=tc.constraint_schema where tc.constraint_type='FOREIGN KEY' and tc.table_schema='public' and tc.table_name like 'work_permit%' order by tc.table_name,tc.constraint_name;
select t.tgname as trigger_name,c.relname as table_name,pg_get_triggerdef(t.oid) as definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname like 'work_permit%' and not t.tgisinternal order by c.relname,t.tgname;
